-- Punionice i cestovne veze među njima (isti podaci kao ev-graph.json).
-- Generirano programom generate_graph.py; ne mijenjajte ručno.

CREATE TABLE station (
    id        VARCHAR(10)      PRIMARY KEY,
    name      VARCHAR(100)     NOT NULL,
    city      VARCHAR(50)      NOT NULL,
    lat       DOUBLE PRECISION NOT NULL,
    lon       DOUBLE PRECISION NOT NULL,
    power_kw  INTEGER          NOT NULL
);

-- Neusmjerena veza: svaki par punionica naveden je jednom (station_a_id < station_b_id).
CREATE TABLE station_link (
    id            BIGINT           GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    station_a_id  VARCHAR(10)      NOT NULL REFERENCES station (id),
    station_b_id  VARCHAR(10)      NOT NULL REFERENCES station (id),
    distance_km   DOUBLE PRECISION NOT NULL,
    CONSTRAINT uk_station_link UNIQUE (station_a_id, station_b_id),
    CONSTRAINT ck_station_link_order CHECK (station_a_id < station_b_id)
);




























































